include!("methods.rs");
fn main(){let a:Vec<_>=std::env::args().collect();let mode=&a[1];let reps:usize=a[2].parse().unwrap();let n=30usize;let ax:usize=a[4].parse().unwrap();let ay:usize=a[5].parse().unwrap();let gap:usize=a[6].parse::<usize>().unwrap()/8;assert!(gap>=n+ax);let mut data:Vec<_>=(0usize..gap+n+ay+32).collect();let base=(64-data.as_ptr()as usize%64)%64/8;let split=base+gap+ay;let(x,y)=data.split_at_mut(split);let x:&mut[usize;30]=(&mut x[base+ax..base+ax+n]).try_into().unwrap();let y:&mut[usize;30]=(&mut y[..n]).try_into().unwrap();let xp=x.as_ptr()as usize;let yp=y.as_ptr()as usize;let f:fn(&mut[usize;30],&mut[usize;30],&mut usize)->(usize,usize)=match mode.as_str(){"original"=>original,"vec"=>vec_batch,"reg"=>reg_batch,"even"=>even_batch,_=>panic!("mode")};let mut skip=0;let now=std::time::Instant::now();for _ in 0..reps{black_box(f(x,y,&mut skip));}let elapsed=now.elapsed().as_nanos();println!("{{\"elapsed_ns\":{},\"reps\":{},\"x_mod64\":{},\"y_mod64\":{},\"distance_bytes\":{}}}",elapsed,reps,xp%64,yp%64,yp-xp);}
